mapper.update:
UPDATE fields
SET label = #{label},
    answer_type = #{answerType},
    required = #{required},
    description = #{description,jdbcType=VARCHAR},
    config = CAST(#{config} AS jsonb),
    show_when = CAST(#{showWhen,jdbcType=VARCHAR} AS jsonb),
    hidden = #{hidden}
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}

UPDATE fields
SET preset_state = CAST(#{presetState} AS jsonb)
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}
  AND preset_key IS NOT NULL

UPDATE fields
SET position = #{position}
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}

mapper.delete:
DELETE FROM fields
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}
  AND kind = 'CUSTOM'
